insert into MST_HOLIDAY(MST_HOLIDAY.CALENDAR_ID,MST_HOLIDAY.CDATE,MST_HOLIDAY.IS_HOLIDAY,MST_HOLIDAY.CREATE_USER,MST_HOLIDAY.CREATE_DEPT,MST_HOLIDAY.CREATE_TIME,MST_HOLIDAY.UPDATE_USER,MST_HOLIDAY.UPDATE_TIME) select A.* from (
select #{item.calendarId,jdbcType=VARCHAR} CALENDAR_ID, #{item.cdate,jdbcType=DATE} CDATE, #{item.isHoliday,jdbcType=VARCHAR} IS_HOLIDAY, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, #{item.createDept,jdbcType=VARCHAR} CREATE_DEPT, #{item.createTime,jdbcType=TIMESTAMP} CREATE_TIME, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, #{item.updateTime,jdbcType=TIMESTAMP} UPDATE_TIME from sysibm.SYSDUMMY1
)A
